{"command": "cat > /app/mystery.c << 'EOF'
#include <math.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct{float x,y,z;} Vec;
typedef struct{Vec orig,dir;} Ray;
typedef struct{Vec p,n; int hit; float t;} Hit;

typedef struct{int w,h; Vec **px;} Image;

static Vec vec(float x,float y,float z){Vec v={x,y,z}; return v;}
static Vec vadd(Vec a, Vec b){return vec(a.x+b.x,a.y+b.y,a.z+b.z);} 
static Vec vsub(Vec a, Vec b){return vec(a.x-b.x,a.y-b.y,a.z-b.z);} 
static Vec vmul(Vec a, float s){return vec(a.x*s,a.y*s,a.z*s);} 
static float vdot(Vec a, Vec b){return a.x*b.x + a.y*b.y + a.z*b.z;}
static float vlen(Vec a){return sqrtf(vdot(a,a));}
static Vec vnorm(Vec a){float l=vlen(a); return l?vmul(a,1.0f/l):a;}
static Vec ray_at(const Ray *r,float t){return vadd(r->orig, vmul(r->dir,t));}

static Hit sphere_intersect(const Ray *r, Vec c, float radius){
    Hit h={0};
    Vec oc = vsub(r->orig, c);
    float a = vdot(r->dir, r->dir);
    float b = 2.0f*vdot(oc, r->dir);
    float cc = vdot(oc, oc) - radius*radius;
    float disc = b*b - 4.0f*a*cc;
    if(disc < 0.0f) return h;
    float sq = sqrtf(disc);
    float t = (-b - sq)/(2.0f*a);
    if(t <= 0.001f){
        t = (-b + sq)/(2.0f*a);
        if(t <= 0.001f) return h;
    }
    h.hit=1; h.t=t; h.p = ray_at(r,t); h.n = vnorm(vsub(h.p,c));
    return h;
}

static Vec sky_color(const Ray *r){
    float t = 0.5f*(r->dir.y + 1.0f);
    Vec a = vec(1.0f,1.0f,1.0f);
    Vec b = vec(0.5f,0.7f,1.0f);
    return vadd(vmul(a,1.0f-t), vmul(b,t));
}

static int is_in_shadow(Vec point, Vec light_dir, Vec sphere_c, float radius){
    Ray r; r.orig=point; r.dir=vnorm(light_dir);
    Hit h = sphere_intersect(&r, sphere_c, radius);
    return h.hit;
}

static Vec trace(const Ray *r){
    const Vec sphere_c = {0.0f,0.0f,-1.5f};
    const float sphere_r = 0.8f;
    const float tmin = 0.001f;

    Hit h = sphere_intersect(r, sphere_c, sphere_r);
    if(h.hit){
        Vec light_dir = vnorm(vec(-1.0f,-1.0f,-1.0f));
        float diff = fmaxf(0.0f, vdot(h.n, vmul(light_dir,-1.0f)));
        Vec base = vec(0.8f,0.2f,0.2f);
        Vec col = vmul(base, diff);
        col = vadd(col, vec(0.4f,0.4f,0.4f));
        return col;
    }

    // ground plane y = -0.5
    float denom = r->dir.y;
    if(fabsf(denom) > 0.0001f){
        float t = (-0.5f - r->orig.y) / denom;
        if(t > tmin){
            Vec p = ray_at(r,t);
            float checker = (floorf(p.x) + floorf(p.z)) * 0.5f;
            float pattern = checker - floorf(checker); // 0 or 0.5
            float shade = pattern < 0.25f ? 0.26f : 0.59f; // approximate 67/255 or 152/255
            Vec col = vec(shade, shade, shade);
            // shadows
            Vec light_dir = vnorm(vec(-1.0f,-1.0f,-1.0f));
            if(is_in_shadow(p, light_dir, sphere_c, sphere_r)){
                col = vmul(col, 0.3f);
            }
            return col;
        }
    }

    return sky_color(r);
}

static Image allocate_image(int w,int h){
    Image img; img.w=w; img.h=h;
    img.px = (Vec**)malloc(sizeof(Vec*)*h);
    for(int y=0;y<h;y++) img.px[y]=(Vec*)malloc(sizeof(Vec)*w);
    return img;
}
static void free_image(Image *img){
    for(int y=0;y<img->h;y++) free(img->px[y]);
    free(img->px);
}

static void write_image(const char *path, Image *img){
    FILE *f=fopen(path,"w");
    if(!f){
        fprintf(stderr,"Error: Could not open %s for writing\n", path);
        return;
    }
    fprintf(f,"P3\n%d %d\n255\n", img->w, img->h);
    for(int y=0;y<img->h;y++){
        for(int x=0;x<img->w;x++){
            Vec c = img->px[y][x];
            float r = fminf(fmaxf(c.x,0.0f),1.0f);
            float g = fminf(fmaxf(c.y,0.0f),1.0f);
            float b = fminf(fmaxf(c.z,0.0f),1.0f);
            int ir = (int)(r*255.99f);
            int ig = (int)(g*255.99f);
            int ib = (int)(b*255.99f);
            fprintf(f,"%d %d %d\n", ir, ig, ib);
        }
    }
    fclose(f);
    fprintf(stderr,"Wrote image to %s\n", path);
}

int main(){
    const int width=800, height=600;
    fprintf(stderr,"Creating high-resolution image: %dx%d\n", width, height);
    fprintf(stderr,"This will be downsampled with ffmpeg after rendering\n");

    Vec v = vnorm(vec(1.0f,1.0f,1.0f));
    Image img = allocate_image(width,height);
    fprintf(stderr,"Rendering high-resolution image...\n");

    for(int y=0;y<height;y++){
        float progress = (100.0f * y) / (height-1.0f);
        fprintf(stderr,"\rProgress: %.1f%%", progress);
        float vcoord = (float)y/(height-1.0f);
        float ubase = 2.6666667f * 0.0f; // unused
        for(int x=0;x<width;x++){
            float u = (float)x/(width-1.0f);
            float px = 2.6666667f * u - 1.3333333f;
            float py = 1.0f - 2.0f * vcoord;
            Ray r; r.orig=vec(0.0f,0.0f,0.0f); r.dir=vnorm(vec(px,py,-1.0f));
            Vec col = trace(&r);
            img.px[y][x]=col;
        }
    }
    fprintf(stderr,"\nRendering complete\n");
    write_image("image.ppm", &img);
    fprintf(stderr,"Done.\n");
    free_image(&img);
    return 0;
}
EOF
"}

