        for(int x=0;x<img->w;x++){
            Vec c = img->px[y][x];
            float r = fminf(fmaxf(c.x,0.0f),1.0f);
            float g = fminf(fmaxf(c.y,0.0f),1.0f);
            float b = fminf(fmaxf(c.z,0.0f),1.0f);
            int ir = (int)(r*255.99f);
            int ig = (int)(g*255.99f);
            int ib = (int)(b*255.99f);
            fprintf(f,"%d %d %d\n", ir, ig, ib);
        }
    }
    fclose(f);
    fprintf(stderr,"Wrote image to %s\n", path);
}

int main(){
    const int width=800, height=600;
    fprintf(stderr,"Creating high-resolution image: %dx%d\n", width, height);
    fprintf(stderr,"This will be downsampled with ffmpeg after rendering\n");

    Vec v = vnorm(vec(1.0f,1.0f,1.0f));
    Image img = allocate_image(width,height);
    fprintf(stderr,"Rendering high-resolution image...\n");

    for(int y=0;y<height;y++){
        float progress = (100.0f * y) / (height-1.0f);
        fprintf(stderr,"\rProgress: %.1f%%", progress);
        float vcoord = (float)y/(height-1.0f);
        float ubase = 2.6666667f * 0.0f; // unused
        for(int x=0;x<width;x++){
            float u = (float)x/(width-1.0f);
            float px = 2.6666667f * u - 1.3333333f;
            float py = 1.0f - 2.0f * vcoord;
            Ray r; r.orig=vec(0.0f,0.0f,0.0f); r.dir=vnorm(vec(px,py,-1.0f));
            Vec col = trace(&r);
            img.px[y][x]=col;
        }
    }
    fprintf(stderr,"\nRendering complete\n");
    write_image("image.ppm", &img);
    fprintf(stderr,"Done.\n");
    free_image(&img);
    return 0;
}
